def roman_to_int(s):
    vals = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0

    # Iterate through the string in reverse to handle subtractive logic easily
    for char in reversed(s):
        current_value = vals[char]
        if current_value < prev_value:
            total -= current_value
        else:
